    public ContactService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ContactEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ContactRepository.class) );
		this.validator		= applicationContext.getBean(ContactValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Contact
	 */
		public Contact createContact( CreateContactCommand command ) {

		Contact entity = new Contact();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setContactId( command.getContactId() );
            entity.setFirstName( command.getFirstName() );
            entity.setLastName( command.getLastName() );
            entity.setTitle( command.getTitle() );
            entity.setEmail( command.getEmail() );
            entity.setPhone( command.getPhone() );
            entity.setMobile( command.getMobile() );
            entity.setMailingAddress( command.getMailingAddress() );
            entity.setPreferredContactMethod( command.getPreferredContactMethod() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Contact {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateContactCommand
	 * @return		Contact
	 */
	public Contact updateContact( UpdateContactCommand command ) {

		Contact entity = new Contact();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setContactId( command.getContactId() );
            entity.setFirstName( command.getFirstName() );
            entity.setLastName( command.getLastName() );
            entity.setTitle( command.getTitle() );
            entity.setEmail( command.getEmail() );
            entity.setPhone( command.getPhone() );
            entity.setMobile( command.getMobile() );
            entity.setMailingAddress( command.getMailingAddress() );
            entity.setOrganization( command.getOrganization() );
            entity.setAccount( command.getAccount() );
            entity.setOwner( command.getOwner() );
            entity.setActivities( command.getActivities() );
            entity.setOpportunities( command.getOpportunities() );
            entity.setCases( command.getCases() );
            entity.setCampaigns( command.getCampaigns() );
            entity.setNotes( command.getNotes() );
            entity.setEmailMessages( command.getEmailMessages() );
            entity.setPreferredContactMethod( command.getPreferredContactMethod() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Contact {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteContactCommand
	 */
	public void delete( DeleteContactCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getContactId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Contact {0} ", id );

	}

	/**
	 * Method to retrieve the Contact via ContactFetchOneSummary
	 * @param 	summary ContactFetchOneSummary
	 * @return 	ContactFetchOneResponse
	 */
	public Contact getContact( ContactFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ContactFetchOneSummary arg cannot be null" );

		Contact entity = null;
		UUID id = summary.getContactId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Contact using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Contacts
	 *
	 * @return 	List<Contact>
	 */
    public List<Contact> getAllContact() {
		List<Contact> list = projector.findAll( new FindAllContactQuery() );
		return list;
	}

